/// <summary>
/// PricingAttribute of table <c>SalesTable</c> field DefaultDimension.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::SalesTable, GUPPricingAttributeSourceLevel::Header)]
internal class GUPPricingAttributeSalesTableDefaultDimension extends GUPPricingAttributeSalesTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(SalesTable, DefaultDimension);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::Integer);
    SalesTable salesTable;
    while select DefaultDimension from salesTable
        group by DefaultDimension
    {
        ret.add(salesTable.DefaultDimension);
    }
    return ret;
}

    protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
    {
        QueryBuildRange qbr;

        qbr = _qbds.addRange(fieldNum(SalesTable, DefaultDimension));
        qbr.value(queryValue(_value));
    }
